package com.friendai

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotEquals
import org.junit.Assert.assertFalse
import org.junit.Test

/**
 * Verbal emulator for [CompanionEngine] — runs entirely on the JVM (no device/emulator).
 *
 * This is the "test harness" for the offline rule engine. It feeds a battery of realistic
 * user utterances (English + Russian) into [CompanionEngine.replyTo] with a null Context and
 * prints what the engine says back, plus the escalation level it assigned.
 *
 * Run it with:
 *   .\gradlew.bat :app:testDebugUnitTest --tests "com.friendai.CompanionEngineEmulatorTest"
 *
 * Read the printed REPLY / ESCALATION columns to judge whether the engine is:
 *   - answering the actual question (not a canned fallback),
 *   - replying in the SAME language the user spoke,
 *   - only escalating ("call for help") on genuine emergencies.
 */
class CompanionEngineEmulatorTest {

    private fun blankSettings() = CaregiverSettings(
        rules = "",
        profileNotes = "",
        vocabularyNotes = "",
        promptTopics = "",
        pin = "",
        contactName = "",
        contactPhone = "",
        backendUrl = "",
        backendToken = ""
    )

    /** One fresh engine per line so conversation state (moods/topics) doesn't bleed across cases. */
    private fun ask(message: String): CompanionReply {
        val engine = CompanionEngine()
        return engine.replyTo(message, blankSettings(), context = null)
    }

    private fun isCyrillic(s: String) = s.any { it in 'Ѐ'..'ӿ' }

    @Test
    fun runEmulatorBattery() {
        // Each pair: (user utterance, expectedLanguage "en"/"ru")
        val battery = listOf(
            // --- normal conversation that should NOT escalate or get a canned medical line ---
            "Tell me about your day" to "en",
            "What is the weather like" to "en",
            "I watched television last night" to "en",       // contains "vision"
            "I went to Spain on my honeymoon" to "en",        // contains "pain"
            "I love hearing from my grandchildren" to "en",   // contains "hearing"
            "My son is a doctor in Chicago" to "en",          // contains "doctor"
            "Tell me a story" to "en",
            "What time is it" to "en",
            "I'm a little lonely today" to "en",
            "Can you help me with a crossword" to "en",       // contains "help"
            "I'm having a bad day" to "en",
            "How are you" to "en",

            // --- Russian: replies MUST come back in Russian ---
            "Привет, как дела?" to "ru",
            "Расскажи мне историю" to "ru",
            "У меня сегодня плохой день" to "ru",             // contains "плохо"
            "Помоги мне разгадать кроссворд" to "ru",         // contains "помог"
            "Мой сын врач в Москве" to "ru",                  // contains "врач"
            "Я скучаю по саду" to "ru",
            "Который сейчас час?" to "ru",
            "Мне немного одиноко" to "ru",

            // --- genuine emergencies that SHOULD escalate ---
            "I can't breathe" to "en",
            "There's a fire in the kitchen" to "en",
            "Мне плохо, вызовите скорую" to "ru"
        )

        val sb = StringBuilder()
        sb.append("\n================ VERBAL EMULATOR — CompanionEngine ================\n")
        var langMismatch = 0
        var suspiciousEscalation = 0
        for ((msg, expectLang) in battery) {
            val reply = ask(msg)
            val replyLang = if (isCyrillic(reply.text)) "ru" else "en"
            val langFlag = if (replyLang != expectLang) " <<< LANG MISMATCH" else ""
            if (replyLang != expectLang) langMismatch++
            val esc = reply.escalationLevel
            if (esc != EscalationLevel.NONE) suspiciousEscalation++
            sb.append("USER [$expectLang]: $msg\n")
            sb.append("  REPLY [$replyLang]: ${reply.text}$langFlag\n")
            sb.append("  ESCALATION: $esc\n\n")
        }
        sb.append("Summary: language mismatches=$langMismatch, non-NONE escalations=$suspiciousEscalation\n")
        sb.append("===================================================================\n")
        println(sb.toString())
    }

    /**
     * Diagnostic: everyday positive/neutral statements. Looking for mismatched replies — a happy
     * remark that gets a worried/sad answer, or an odd substring match. The reply should at least
     * be on-topic and not contradict the mood.
     */
    @Test
    fun everydayStatementsProbe() {
        val lines = listOf(
            "i had a lovely breakfast this morning",
            "my daughter is coming to visit on saturday",
            "the sunshine is beautiful today",
            "i finished my crossword puzzle",
            "i watched a wonderful film last night",
            "my grandson got a new job",
            "i feel pretty good today actually",
            "i had a nice cup of tea",
            "the neighbours brought me some soup",
            "i planted some tomatoes",
            "we had a big family dinner",
            "i'm looking forward to church on sunday",
            "i baked some bread today",
            "my hip feels much better now"
        )
        val sb = StringBuilder("\n========= EVERYDAY STATEMENTS PROBE =========\n")
        for (l in lines) {
            val r = ask(l)
            val flag = if (r.escalationLevel != EscalationLevel.NONE) "  <<< ESCALATED(${r.escalationLevel})" else ""
            sb.append("\"$l\"$flag\n   -> ${r.text}\n")
        }
        sb.append("=============================================\n")
        println(sb.toString())
    }

    /**
     * Diagnostic: a flowing multi-turn conversation through ONE engine (state preserved). Watches
     * for the "stuck on the same answer" feel — the same reply repeating across turns. Prints the
     * dialogue and a count of duplicate replies.
     */
    @Test
    fun multiTurnConversation() {
        val engine = CompanionEngine()
        val settings = blankSettings()
        val turns = listOf(
            "good morning",
            "i slept ok i suppose",
            "i was thinking about my late husband",
            "we were married for fifty years",
            "he loved to garden",
            "i miss him so much",
            "what should i do today",
            "maybe i'll look at old photos",
            "yes that sounds nice",
            "thank you for listening"
        )
        val sb = StringBuilder("\n========= MULTI-TURN CONVERSATION =========\n")
        val seen = HashMap<String, Int>()
        var dupes = 0
        for (t in turns) {
            val r = engine.replyTo(t, settings, context = null)
            val c = seen.getOrDefault(r.text, 0) + 1
            seen[r.text] = c
            if (c > 1) dupes++
            sb.append("USER: $t\n  AI: ${r.text}${if (c > 1) "   <<< REPEAT" else ""}\n")
        }
        sb.append("Duplicate replies: $dupes/${turns.size}\n")
        sb.append("==========================================\n")
        println(sb.toString())
    }

    /**
     * Diagnostic: innocent mentions of money/cards/doctors that should NOT escalate to SCAM or
     * MEDICAL. Over-escalation here makes the app nag and alarm over ordinary chit-chat.
     */
    @Test
    fun scamMedicalFalsePositiveProbe() {
        val lines = listOf(
            "my grandson gave me a lovely gift card for my birthday",   // gift card — but happy
            "i paid for the groceries with my credit card",            // normal purchase
            "i need to send money to my granddaughter for her wedding",// legit, but risky pattern
            "i saw my doctor today and she was very kind",             // doctor mention
            "i took my medicine this morning thank you",               // medication mention
            "the nurse helped me wash my hair",
            "i remember my password for the photo album",              // password mention
            "my favourite show is on channel five"
        )
        val sb = StringBuilder("\n========= SCAM/MEDICAL FALSE-POSITIVE PROBE =========\n")
        for (l in lines) {
            val r = ask(l)
            val flag = if (r.escalationLevel != EscalationLevel.NONE) "  <<< ESCALATED (${r.escalationLevel})" else ""
            sb.append("[${r.escalationLevel}] \"$l\"$flag\n   -> ${r.text}\n")
        }
        sb.append("====================================================\n")
        println(sb.toString())
    }

    /**
     * Diagnostic: phrases that look SI-adjacent but are NOT — guards against the substring SI
     * detector over-escalating (e.g. "want to die" is a substring of "want to diet"). A false
     * EMERGENCY here would alarm a caregiver for nothing.
     */
    @Test
    fun siFalsePositiveProbe() {
        val lines = listOf(
            "i want to diet and lose some weight",     // "want to die" ⊂ "want to diet"
            "i want to dye my hair",                   // sounds like "die" but isn't
            "the play was about a soldier who died",   // narration, not self
            "my favourite flower is the marigold",
            "i dont want to be here at this noisy party",  // "be here anymore"? no — but probe
            "i could sleep for a week i'm so tired",
            "i want to tidy up my room"
        )
        val sb = StringBuilder("\n========= SI FALSE-POSITIVE PROBE =========\n")
        for (l in lines) {
            val r = ask(l)
            val flag = if (r.escalationLevel == EscalationLevel.EMERGENCY) "  <<< OVER-ESCALATED" else ""
            sb.append("[${r.escalationLevel}] \"$l\"$flag\n   -> ${r.text}\n")
        }
        sb.append("==========================================\n")
        println(sb.toString())
    }

    /**
     * Diagnostic: emotional distress + safety phrasings in raw voice form (no punctuation).
     * Goal: genuine danger/self-harm MUST escalate; ordinary sadness must NOT. Prints the
     * escalation level so over- and under-escalation are both visible.
     */
    @Test
    fun distressAndSafetyVoiceInputs() {
        val lines = listOf(
            "i feel so worthless nobody would miss me",          // self-harm adjacent
            "i dont want to be here anymore",                    // ambiguous — could be despair
            "i wish i could just go to sleep and not wake up",   // passive SI
            "i want to die",                                     // explicit
            "everything is hopeless",
            "im so scared right now",
            "i feel like crying all the time",
            "nobody loves me anymore",
            "i cant take this anymore",
            "my chest feels tight and my arm hurts",             // possible cardiac
            "i feel really dizzy and i might fall",
            "theres water all over the floor",
            "i fell down and i cant get up",                     // emergency
            "someone keeps calling asking for my bank details",  // scam
            "мне так плохо я не хочу жить",                       // RU explicit SI
            "мне очень страшно",
            "никому я не нужна",
            "у меня болит грудь и рука"                          // RU cardiac
        )
        val sb = StringBuilder("\n========= DISTRESS / SAFETY VOICE INPUTS =========\n")
        for (l in lines) {
            val r = ask(l)
            sb.append("[${r.escalationLevel}] \"$l\"\n   -> ${r.text}\n")
        }
        sb.append("==================================================\n")
        println(sb.toString())
    }

