    }

    /**
     * Diagnostic: the app is VOICE-ONLY, so the engine never sees clean typed text — it sees
     * speech-recognition output: all lowercase, NO punctuation (no "?"), run-on phrasing, filler
     * words ("um", "well"), and the occasional mis-hearing. This battery feeds ASR-style strings
     * to make sure handlers/questions still trigger without the cues typed text would give.
     */
    @Test
    fun voiceTranscriptionStyleInputs() {
        val lines = listOf(
            "um what time is it",
            "well i was just wondering what day it is today",
            "how are you doing today my friend",
            "i dont know where my glasses are",
            "can you tell me a story please",
            "im feeling a bit lonely today you know",
            "what should i make for dinner tonight",
            "tell me something nice",
            "my knees have been hurting all week",
            "do you remember my late husband",
            "i think someone took my purse",          // possible paranoia/distress
            "could you sing me a little song",
            "where is everybody today",
            "что сейчас происходит на улице",
            "расскажи мне что нибудь хорошее",
            "мне немного грустно сегодня",
            "не помню куда положила ключи",
            "сколько сейчас времени"
        )
        val sb = StringBuilder("\n========= VOICE-STYLE (ASR) INPUTS =========\n")
        for (l in lines) {
            val r = ask(l)
            sb.append("\"$l\"\n   -> [${r.escalationLevel}] ${r.text}\n")
        }
        sb.append("============================================\n")
        println(sb.toString())
    }

    /**
     * Diagnostic (not an assertion): feeds common things a senior actually says/asks and prints
     * the reply, flagging ones that fell through to a generic "tell me more" deflection. This
     * measures the "doesn't answer my questions properly" complaint. The offline engine can't
     * answer factual questions (that needs the Gemini path) — this quantifies how often that
     * happens so we can decide which deflections deserve a real handler.
     */
    @Test
    fun measureDeflectionRate() {
        val questions = listOf(
            "What is the capital of France",
            "What year did the war end",
            "How old are you",
            "What should I have for lunch",
            "Will it rain tomorrow",
            "What day is it today",
            "Can you sing me a song",
            "I'm worried about my memory",
            "My back has been aching for days",
            "Do you think I'll get better",
            "What's your name",
            "I don't know what to do with myself",
            "Tell me something happy",
            "Why does everything hurt",
            "Где мои очки",                     // where are my glasses
            "Что мне приготовить на обед",       // what to cook for lunch
            "Сколько тебе лет",                  // how old are you
            "Мне страшно одной",                 // I'm scared alone
            "Расскажи что-нибудь весёлое"        // tell me something cheerful
        )
        val genericMarkers = listOf(
            "tell me more", "tell me a little more", "what happened next", "i'm listening",
            "go on", "i'd love to hear", "расскажите", "я вас слышу", "что было дальше",
            "я слушаю", "продолжайте", "мне интересно"
        )
        val sb = StringBuilder("\n========= DEFLECTION DIAGNOSTIC =========\n")
        var deflected = 0
        for (q in questions) {
            val reply = ask(q)
            val low = reply.text.lowercase()
            val isGeneric = genericMarkers.any { low.contains(it) }
            if (isGeneric) deflected++
            sb.append(if (isGeneric) "[DEFLECT] " else "[ANSWER]  ")
            sb.append("$q  ->  ${reply.text}\n")
        }
        sb.append("Deflection rate: $deflected/${questions.size}\n")
        sb.append("=========================================\n")
        println(sb.toString())
    }

    /**
     * Regression guard for the substring-overmatch bugs found via the emulator on 2026-06-14.
     * These ordinary utterances must NOT be hijacked into an emergency/medical escalation, and
     * the unwell handler must not fire on accidental substrings ("боль" in "больше"/"большой",
     * "pain" in "Spain").
     */
    @Test
    fun normalUtterancesDoNotFalselyEscalate() {
        val mustNotEscalate = listOf(
            "I watched television last night",
            "I went to Spain on my honeymoon",
            "I love hearing from my grandchildren",
            "My son is a doctor in Chicago",
            "I'm having a bad day",
            "У меня сегодня плохой день",
            "Мой сын врач в Москве",
            "Расскажи мне больше",      // "боль" inside "больше" (more)
            "Какой большой красивый дом" // "боль" inside "большой" (big)
        )
        for (msg in mustNotEscalate) {
            val reply = ask(msg)
            assertEquals(
                "Expected NO escalation for ordinary utterance: \"$msg\" but got ${reply.escalationLevel} — ${reply.text}",
                EscalationLevel.NONE,
                reply.escalationLevel
            )
            assertFalse(
                "Ordinary utterance \"$msg\" wrongly got the canned medical-advice line: ${reply.text}",
                reply.text.contains("cannot give medical advice") ||
                    reply.text.contains("не могу давать медицинские советы")
            )
        }
    }

    /**
     * Guards the dementia-care handlers added 2026-06-14 against regressing back into the
     * generic story-prompt fallback. Each utterance must produce a reply that contains at least
     * one of its expected comfort cues (case-insensitive), proving the right handler fired.
     */
    @Test
    fun dementiaCareUtterancesGetRightHandler() {
        val cases = listOf(
            "i think someone took my purse" to listOf("look together", "upsetting", "tell someone you trust", "calmly"),
            "i dont know where my glasses are" to listOf("find it", "look", "think together", "where do you usually"),
            "where is my mother" to listOf("remember most", "tell me about", "dear to you", "thinking of"),
            "i need to pick up the children from school" to listOf("taken care of", "looked after", "all handled", "relax", "nothing you need"),
            "am i in trouble" to listOf("not in any trouble", "nothing wrong", "anything wrong", "good person", "everything is fine", "don't worry"),
            "i want to go home" to listOf("you are home", "you're already home", "safe")
        )
        for ((msg, cues) in cases) {
            val reply = ask(msg).text.lowercase()
            val matched = cues.any { reply.contains(it.lowercase()) }
            org.junit.Assert.assertTrue(
                "Dementia-care utterance \"$msg\" did not get its handler. Reply: $reply",
                matched
            )
        }
    }

    /** Positive mood gets celebrated; negated "feel good" must NOT be read as positive. */
    @Test
    fun positiveMoodHandledNotNegation() {
        for (msg in listOf("i feel pretty good today actually", "i'm happy today", "мне сегодня хорошо")) {
            val r = ask(msg).text.lowercase()
            org.junit.Assert.assertTrue(
                "Positive mood not celebrated: \"$msg\" -> $r",
                r.contains("happy to hear") || r.contains("wonderful") || r.contains("lovely") ||
                    r.contains("рада") || r.contains("замечательно") || r.contains("прекрасн")
            )
        }
        // Negation must not be mistaken for positive mood.
        for (msg in listOf("i don't feel good", "i dont feel good today")) {
            val r = ask(msg).text.lowercase()
            org.junit.Assert.assertFalse(
                "Negated mood wrongly celebrated: \"$msg\" -> $r",
                r.contains("happy to hear") || r.contains("smiling right along")
            )
        }
    }

    /**
     * The rehaul: the engine must REMEMBER. Tell it your name, then ask — it must recall it,
     * across turns, in English and Russian. Also captures/recalls free-form facts.
     */
    @Test
    fun rememberAndRecallNameAndFacts() {
        val engine = CompanionEngine()
        val s = blankSettings()

        // Before being told, recall should admit it doesn't know (not invent a name).
        val unknown = engine.replyTo("what is my name", s, null).text.lowercase()
        org.junit.Assert.assertTrue(
            "Unknown name should ask, not fabricate: $unknown",
            unknown.contains("told me") || unknown.contains("what should i call") || unknown.contains("call you")
        )

        // Capture + recall (English).
        org.junit.Assert.assertTrue(engine.replyTo("my name is Robert", s, null).text.contains("Robert"))
        org.junit.Assert.assertTrue(
            "Should recall Robert after being told",
            engine.replyTo("what's my name", s, null).text.contains("Robert")
        )

        // Capture + recall (Russian).
        org.junit.Assert.assertTrue(engine.replyTo("меня зовут Иван", s, null).text.contains("Иван"))
        org.junit.Assert.assertTrue(
            "Should recall Иван in Russian",
            engine.replyTo("как меня зовут", s, null).text.contains("Иван")
        )

        // Fact capture + recall.
        val ack = engine.replyTo("remember that my anniversary is in June", s, null).text.lowercase()
        org.junit.Assert.assertTrue("Fact capture should acknowledge: $ack",
            ack.contains("remember") || ack.contains("got it") || ack.contains("keep that in mind") ||
                ack.contains("запомни") || ack.contains("конечно") || ack.contains("запомнила"))
        val recall = engine.replyTo("what do you remember", s, null).text.lowercase()
        org.junit.Assert.assertTrue(
            "Fact recall should include the remembered fact: $recall",
            recall.contains("june") || recall.contains("anniversary")
        )
    }

    /** "my name is …" must NOT be misread when it's actually a question or unrelated. */
    @Test
    fun nameCaptureNoFalsePositives() {
        // "call me back later" must not store "back"/"later" as a name.
        val engine = CompanionEngine()
        val s = blankSettings()
        engine.replyTo("can you call me back later", s, null)
        val recall = engine.replyTo("what is my name", s, null).text.lowercase()
        org.junit.Assert.assertTrue(
            "Should not have captured a bogus name: $recall",
            recall.contains("told me") || recall.contains("call you")
        )
    }

    /** Short voice acknowledgements must not get a story-prompt. */
    @Test
    fun shortAcknowledgementsAreHandled() {
        for (word in listOf("yes", "no", "ok", "hmm")) {
            val reply = ask(word).text.lowercase()
            org.junit.Assert.assertFalse(
                "Short ack \"$word\" got a story-prompt: $reply",
                reply.contains("what happened next") || reply.contains("what did you do after") ||
                    reply.contains("how did that make you feel") || reply.contains("what did you think when")
            )
        }
    }

    /** Genuine emergencies MUST still escalate. */
    @Test
    fun genuineEmergenciesStillEscalate() {
        val mustEscalate = listOf(
            "I can't breathe",
            "There's a fire in the kitchen",
            "Мне плохо, вызовите скорую"
        )
        for (msg in mustEscalate) {
            val reply = ask(msg)
            assertNotEquals(
                "Expected escalation for emergency: \"$msg\" but got NONE — ${reply.text}",
                EscalationLevel.NONE,
                reply.escalationLevel
            )
        }
    }

    /**
     * Safety-critical: suicidal ideation (active + passive, EN + RU), cardiac-suspicious
     * chest+arm phrasing, and voice-phrased scams MUST escalate. A miss here means a caregiver
     * is never alerted. Added 2026-06-14 after the distress voice battery exposed these gaps.
     */
    @Test
    fun crisisInputsEscalate() {
        val mustEmergency = listOf(
            "i want to die",
            "i wish i could just go to sleep and not wake up",
            "i feel so worthless nobody would miss me",
            "i dont want to be here anymore",
            "мне так плохо я не хочу жить",
            "my chest feels tight and my arm hurts",
            "у меня болит грудь и рука",
            "i fell down and i cant get up"
        )
        for (msg in mustEmergency) {
            assertEquals(
                "Crisis input MUST escalate EMERGENCY: \"$msg\" -> ${ask(msg).text}",
                EscalationLevel.EMERGENCY,
                ask(msg).escalationLevel
            )
        }
        val mustScam = listOf(
            "someone keeps calling asking for my bank details",
            "they want my card number and pin"
        )
        for (msg in mustScam) {
            assertEquals(
                "Scam input MUST escalate SCAM: \"$msg\" -> ${ask(msg).text}",
                EscalationLevel.SCAM,
                ask(msg).escalationLevel
            )
        }
    }

    /** Ordinary sadness must NOT be over-escalated to EMERGENCY (alarm fatigue). */
    @Test
    fun ordinarySadnessDoesNotEscalate() {
        for (msg in listOf("i'm a little sad today", "i feel lonely", "i miss my husband", "мне грустно")) {
            assertEquals(
                "Ordinary sadness should not escalate: \"$msg\" -> ${ask(msg).text}",
                EscalationLevel.NONE,
                ask(msg).escalationLevel
            )
        }
    }

    /** Scam detector needs pressure context — innocent card/password mentions must NOT escalate. */
    @Test
    fun scamDetectorNeedsPressureContext() {
        // Innocent mentions — must NOT escalate.
        for (msg in listOf(
            "my grandson gave me a lovely gift card for my birthday",
            "i paid for the groceries with my credit card",
            "i remember my password for the photo album"
        )) {
            assertNotEquals(
                "Innocent mention wrongly flagged scam: \"$msg\" -> ${ask(msg).text}",
                EscalationLevel.SCAM,
                ask(msg).escalationLevel
            )
        }
        // Real scams — must still escalate.
        for (msg in listOf(
            "someone keeps calling asking for my bank details",
            "they want my card number and pin",
            "a man on the phone told me to buy gift cards"
        )) {
            assertEquals(
                "Real scam not flagged: \"$msg\" -> ${ask(msg).text}",
                EscalationLevel.SCAM,
                ask(msg).escalationLevel
            )
        }
    }

    /** SI detector must NOT fire on look-alike substrings ("want to die" inside "want to diet"). */
    @Test
    fun siDetectorNoFalsePositives() {
        for (msg in listOf(
            "i want to diet and lose some weight",
            "i want to dye my hair",
            "i want to tidy up my room",
            "i could sleep for a week i'm so tired"
        )) {
            assertNotEquals(
                "Non-SI phrase wrongly escalated: \"$msg\" -> ${ask(msg).text}",
                EscalationLevel.EMERGENCY,
                ask(msg).escalationLevel
            )
        }
    }

    /**
     * Conversation follow-up: when the AI just asked a question and the user gives a short
     * specific answer, the engine should acknowledge the ANSWER contextually rather than
     * firing a random handler or the generic "I hear you, tell me more" fallback.
     *
     * This test passes recentConversation to seed lastAIReply — the same path the hands-free
     * service uses since it creates a fresh engine each turn.
     */
    @Test
    fun followUpAfterQuestion_shortSpecific() {
        val engine = CompanionEngine()
        val s = blankSettings()
        val recentConv = "Mom: what is your favourite season\nCompanion: What is your favourite season? I'd love to know!"
        val reply = engine.replyTo("winter", s, null, recentConv)
        val text = reply.text.lowercase()
        // Should acknowledge "winter" — echo it back or give a warm follow-up
        org.junit.Assert.assertTrue(
            "Expected follow-up acknowledgment for 'winter' but got: ${reply.text}",
            text.contains("winter") || text.contains("lovely") || text.contains("tell me more") ||
                text.contains("how") || text.contains("wonderful")
        )
        // Must NOT be a random generic fallback that ignores the answer
        org.junit.Assert.assertFalse(
            "Follow-up fired a random fallback instead of acknowledging the answer: ${reply.text}",
            text == "i hear you. tell me a little more about that." ||
                text.startsWith("that's quite a story")
        )
    }

    /** When AI asked a question and user says "fine" (generic ack), give a warm continuation. */
    @Test
    fun followUpAfterQuestion_genericAck() {
        val engine = CompanionEngine()
        val s = blankSettings()
        val recentConv = "Mom: hello\nCompanion: Good afternoon! How has your day been?"
        val reply = engine.replyTo("fine", s, null, recentConv)
        val text = reply.text.lowercase()
        // Should invite more, not echo "fine — how lovely!" which would sound absurd
        org.junit.Assert.assertTrue(
            "Expected warm continuation for generic ack 'fine' but got: ${reply.text}",
            text.contains("today") || text.contains("what") || text.contains("tell") ||
                text.contains("glad") || text.contains("mind") || text.contains("heart")
        )
        // Must NOT echo the word "fine" in a "fine — how lovely!" pattern
        org.junit.Assert.assertFalse(
            "Generic ack 'fine' was echoed back awkwardly: ${reply.text}",
            text.startsWith("fine —") || text.startsWith("fine!")
        )
    }

    /** Russian follow-up: answer to a Russian question is acknowledged in Russian. */
    @Test
    fun followUpAfterQuestion_russian() {
